import type { ComponentType, ReactNode } from "react"

/** Where a route can show: the sidebar (and its drawer), the bottom bar, its More sheet, and the palette's Go to. */
type ShellPlacement = "sidebar" | "mobile" | "more" | "palette"

/**
 * How `<main>` lays out the page. `flow`: as tall as its content, and the page scrolls. `fill`: exactly the height
 * left under the topbar (and above the bottom bar), so a child with `h-full` or `flex-1` fills it and scrolls inside.
 */
type ShellMain = "flow" | "fill"

type ShellRoute = {
  /** Unique among the routes: keys and the palette's command values come from it. */
  id: string
  /** Names the route's link in the sidebar, the bottom bar and the palette. */
  label: string
  href: string
  /** Any icon component, like a lucide icon. Decorative: the label names the route. */
  icon?: ComponentType<{ className?: string }>
  /** The `id` of one of `groups`; without `groups`, the group's label. Routes without one come first, unlabelled. */
  group?: string
  /**
   * In the bottom bar on narrow screens, which has four slots; More opens the rest. `{ order }` places it apart from
   * the sidebar's order: routes sort by `order`, then by their place in the list, and `true` counts as order 0.
   */
  mobile?: boolean | { order: number }
  /**
   * Where it shows; everywhere by default. `["sidebar"]` keeps it out of the bottom bar, More and the palette.
   * Listing `"mobile"` puts it in the bottom bar as `mobile: true` does; leaving `"mobile"` out keeps it out of the
   * bar even with `mobile` set. `"more"` lets More list it when the bar doesn't show it.
   */
  placements?: readonly ShellPlacement[]
  /** Overrides the Shell's `main` while this route is current, like `"fill"` for an editor among scrolling pages. */
  main?: ShellMain
  /** More words the palette matches, like synonyms. */
  keywords?: readonly string[]
  /** A short count or mark beside the label, like 3. It joins the link's name. */
  badge?: ReactNode
}

type ShellRouteGroup = {
  id: string
  label: string
  /** `muted` quiets the group, like sections on their way out. */
  tone?: "default" | "muted"
}

/**
 * The current page: an href, compared exactly, or a matcher for nested routes, called with each route's href. When
 * several routes match, the one with the longest href is current.
 */
type ShellCurrent<Route extends ShellRoute = ShellRoute> = string | ((href: string, route: Route) => boolean)

type ShellRouteSection = {
  id: string
  label?: string
  tone: "default" | "muted"
  routes: ShellRoute[]
}

type MobileRoutes = { shown: ShellRoute[]; rest: ShellRoute[] }

const mobileSlots = 4

function placedIn(route: ShellRoute, placement: ShellPlacement) {
  return route.placements === undefined || route.placements.includes(placement)
}

function sectionRoutes(
  routes: readonly ShellRoute[],
  groups: readonly ShellRouteGroup[] | undefined,
): ShellRouteSection[] {
  const ungrouped: ShellRouteSection = { id: "", tone: "default", routes: [] }
  const sections = new Map<string, ShellRouteSection>()
  for (const group of groups ?? []) {
    sections.set(group.id, { id: group.id, label: group.label, tone: group.tone ?? "default", routes: [] })
  }
  for (const route of routes) {
    let section = route.group === undefined ? undefined : sections.get(route.group)
    if (!section && route.group !== undefined && groups === undefined) {
      section = { id: route.group, label: route.group, tone: "default", routes: [] }
      sections.set(route.group, section)
    }
    const target = section ?? ungrouped
    target.routes.push(route)
  }
  return [ungrouped, ...sections.values()].filter((section) => section.routes.length > 0)
}

function currentRouteId<Route extends ShellRoute>(
  routes: readonly Route[],
  current: ShellCurrent<Route> | undefined,
): string | undefined {
  if (current === undefined) return undefined
  if (typeof current === "string") return routes.find((route) => route.href === current)?.id
  let best: Route | undefined
  for (const route of routes) {
    if (current(route.href, route) && (best === undefined || route.href.length > best.href.length)) best = route
  }
  return best?.id
}

function mobileOrder(route: ShellRoute): number | undefined {
  if (!placedIn(route, "mobile")) return undefined
  if (typeof route.mobile === "object") return route.mobile.order
  return route.mobile || route.placements !== undefined ? 0 : undefined
}

function mobileRoutes(routes: readonly ShellRoute[]): MobileRoutes {
  const candidates: { route: ShellRoute; order: number; index: number }[] = []
  for (const [index, route] of routes.entries()) {
    const order = mobileOrder(route)
    if (order !== undefined) candidates.push({ route, order, index })
  }
  candidates.sort((a, b) => a.order - b.order || a.index - b.index)
  const shown = candidates.slice(0, mobileSlots).map((candidate) => candidate.route)
  return { shown, rest: routes.filter((route) => !shown.includes(route) && placedIn(route, "more")) }
}

export { currentRouteId, mobileRoutes, placedIn, sectionRoutes }
export type { ShellMain, ShellRoute, ShellPlacement, ShellRouteGroup, ShellRouteSection, ShellCurrent, MobileRoutes }

"use client"

import { createContext, use, useMemo } from "react"

import {
  currentRouteId,
  mobileRoutes,
  placedIn,
  sectionRoutes,
  type ShellRoute,
  type ShellRouteGroup,
  type ShellCurrent,
} from "@/components/ui/shell-routes"
import type { SidebarState } from "@/components/ui/use-sidebar-state"

const ShellSidebarContext = createContext<SidebarState | null>(null)

/**
 * The Shell's sidebar state, from inside the Shell (its pages, `actions`, `brand`): `collapsed`, `setCollapsed` and
 * the `controller`, to toggle the sidebar from a command or a menu.
 */
function useShellSidebar(): SidebarState {
  const sidebar = use(ShellSidebarContext)
  if (!sidebar) throw new Error("useShellSidebar must be called inside a Shell")
  return sidebar
}

/** What the shell derives from its routes: rebuilt when the routes change, not on every navigation. */
function useShellRoutes<Route extends ShellRoute>(
  routes: readonly Route[],
  groups: readonly ShellRouteGroup[] | undefined,
  current: ShellCurrent<Route> | undefined,
) {
  const sections = useMemo(
    () =>
      sectionRoutes(
        routes.filter((route) => placedIn(route, "sidebar")),
        groups,
      ),
    [routes, groups],
  )
  const paletteSections = useMemo(
    () =>
      sectionRoutes(
        routes.filter((route) => placedIn(route, "palette")),
        groups,
      ),
    [routes, groups],
  )
  const mobile = useMemo(() => mobileRoutes(routes), [routes])
  const currentId = useMemo(() => currentRouteId(routes, current), [routes, current])
  return { sections, paletteSections, mobile, currentId }
}

export { ShellSidebarContext, useShellRoutes, useShellSidebar }

"use client"

import { memo, useMemo, type MouseEvent } from "react"

import type { ShellRoute, ShellRouteSection, MobileRoutes } from "@/components/ui/shell-routes"
import { isPlainClick } from "@/components/ui/link-primitive"
import type { MobileNavItem } from "@/components/ui/mobile-nav"
import { SidebarGroup, SidebarItem } from "@/components/ui/sidebar"

/** Navigates to a route by id. Stable, so memoized items skip re-rendering. */
type NavigateTo = (id: string) => void

function RouteIcon({ route, className }: { route: ShellRoute; className?: string }) {
  const Icon = route.icon
  return Icon ? <Icon className={className} /> : null
}

// Memoized: on navigation only the item that was current and the one that is now re-render.
const ShellSidebarItem = memo(function ShellSidebarItem({
  route,
  current,
  navigate,
}: {
  route: ShellRoute
  current: boolean
  navigate: NavigateTo
}) {
  return (
    <SidebarItem
      href={route.href}
      current={current}
      icon={<RouteIcon route={route} />}
      badge={route.badge}
      // Always set, so agents can follow every route; without onNavigate it loads the href like a plain link.
      onFollow={() => navigate(route.id)}
    >
      {route.label}
    </SidebarItem>
  )
})

function ShellSidebarSections({
  sections,
  currentId,
  navigate,
}: {
  sections: readonly ShellRouteSection[]
  currentId: string | undefined
  navigate: NavigateTo
}) {
  return sections.map((section) => (
    <SidebarGroup key={section.id} label={section.label} tone={section.tone}>
      {section.routes.map((route) => (
        <ShellSidebarItem key={route.id} route={route} current={route.id === currentId} navigate={navigate} />
      ))}
    </SidebarGroup>
  ))
}

function followClick(event: MouseEvent<HTMLAnchorElement>, id: string, navigate: NavigateTo) {
  if (event.defaultPrevented || !isPlainClick(event.nativeEvent)) return
  event.preventDefault()
  navigate(id)
}

function mobileItem(route: ShellRoute, current: boolean, navigate: NavigateTo | undefined): MobileNavItem {
  const item = { label: route.label, icon: <RouteIcon route={route} />, badge: route.badge, current }
  if (!navigate) return { ...item, href: route.href }
  // oxlint-disable-next-line jsx-a11y/anchor-has-content, jsx-a11y/control-has-associated-label -- MobileNav fills it with the label
  return { ...item, render: <a href={route.href} onClick={(event) => followClick(event, route.id, navigate)} /> }
}

/**
 * The bottom bar's items and overflow. Each route's item is built once as current and once not, so a navigation
 * hands MobileNav the same objects for every route but two, and its memoized slots skip the rest.
 */
function useMobileNavItems(mobile: MobileRoutes, currentId: string | undefined, navigate: NavigateTo | undefined) {
  const variants = useMemo(() => {
    const build = (routes: readonly ShellRoute[]) =>
      routes.map((route) => ({
        id: route.id,
        idle: mobileItem(route, false, navigate),
        current: mobileItem(route, true, navigate),
      }))
    return { shown: build(mobile.shown), rest: build(mobile.rest) }
  }, [mobile, navigate])
  return useMemo(() => {
    const pick = (list: typeof variants.shown) =>
      list.map((variant) => (variant.id === currentId ? variant.current : variant.idle))
    return { items: pick(variants.shown), overflow: pick(variants.rest) }
  }, [variants, currentId])
}

export { ShellSidebarSections, RouteIcon, useMobileNavItems }
export type { NavigateTo }

"use client"

import type { ReactNode } from "react"

import { RouteIcon, type NavigateTo } from "@/components/ui/shell-nav"
import type { ShellRouteSection } from "@/components/ui/shell-routes"
import {
  Command,
  CommandEmpty,
  CommandFooter,
  CommandGroup,
  CommandGroupLabel,
  CommandInput,
  CommandItem,
  CommandItemIcon,
  CommandList,
  type CommandProps,
} from "@/components/ui/command"
import { CommandDialog, CommandDialogContent, type CommandDialogController } from "@/components/ui/command-dialog"

// Keeps the generated commands apart from the consumer's own `commandGroups` values.
const goToPrefix = "shell:go-to:"

type ShellSearchLabels = { palette: string; search: string; searchPlaceholder?: string; empty: string; goTo: string }

type ShellSearchProps = {
  controller: CommandDialogController
  sections: readonly ShellRouteSection[]
  currentId: string | undefined
  navigate: NavigateTo
  labels: ShellSearchLabels
  commandGroups?: ReactNode
  onCommand?: (value: string) => unknown
  /** The search text, to control it. Without it, every open starts from `defaultQuery`. */
  query?: string
  /** The search text each open starts from, when `query` doesn't control it. Empty by default. */
  defaultQuery?: string
  onQueryChange?: CommandProps["onQueryChange"]
  /** Under the list, like key hints. Nothing by default. */
  footer?: ReactNode
}

function ShellSearch({
  controller,
  sections,
  currentId,
  navigate,
  labels,
  commandGroups,
  onCommand,
  query,
  defaultQuery,
  onQueryChange,
  footer,
}: ShellSearchProps) {
  // Route commands are links, which never reach onAction; only the consumer's commands run here.
  const run = async (value: string) => {
    await onCommand?.(value)
    controller.close()
  }
  const follow = (id: string) => {
    // Closed first, so focus is back on the trigger before the route changes.
    controller.close()
    navigate(id)
  }
  return (
    <CommandDialog controller={controller}>
      <CommandDialogContent title={labels.palette}>
        <Command onAction={run} query={query} defaultQuery={defaultQuery} onQueryChange={onQueryChange}>
          <CommandInput aria-label={labels.search} placeholder={labels.searchPlaceholder} />
          <CommandEmpty>{labels.empty}</CommandEmpty>
          <CommandList>
            <CommandGroup>
              <CommandGroupLabel>{labels.goTo}</CommandGroupLabel>
              {sections.flatMap((section) =>
                section.routes.map((route) => {
                  const current = route.id === currentId
                  return (
                    <CommandItem
                      key={route.id}
                      value={`${goToPrefix}${route.id}`}
                      href={route.href}
                      onFollow={() => follow(route.id)}
                      label={route.label}
                      keywords={[...(route.keywords ?? []), ...(section.label === undefined ? [] : [section.label])]}
                      aria-current={current ? "page" : undefined}
                      data-current={current ? "" : undefined}
                      className="group/shell-command"
                    >
                      {route.icon && (
                        <CommandItemIcon>
                          <RouteIcon route={route} />
                        </CommandItemIcon>
                      )}
                      <span className="min-w-0 flex-1 truncate">{route.label}</span>
                      <span
                        aria-hidden="true"
                        data-slot="shell-command-current"
                        className="hidden size-1.5 shrink-0 rounded-full bg-primary group-data-current/shell-command:block in-data-highlighted:bg-current"
                      />
                    </CommandItem>
                  )
                }),
              )}
            </CommandGroup>
            {commandGroups}
          </CommandList>
          {footer !== undefined && <CommandFooter>{footer}</CommandFooter>}
        </Command>
      </CommandDialogContent>
    </CommandDialog>
  )
}

export { ShellSearch, goToPrefix }
export type { ShellSearchLabels, ShellSearchProps }

"use client"

import { useCallback, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react"
import { SearchIcon } from "lucide-react"

import { ShellSidebarSections, useMobileNavItems } from "@/components/ui/shell-nav"
import {
  placedIn,
  type ShellMain,
  type ShellPlacement,
  type ShellRoute,
  type ShellRouteGroup,
  type ShellCurrent,
} from "@/components/ui/shell-routes"
import { ShellSearch, type ShellSearchProps } from "@/components/ui/shell-search"
import {
  CommandDialogOpenButton,
  CommandDialogShortcut,
  CommandDialogTrigger,
  createCommandDialogController,
} from "@/components/ui/command-dialog"
import { MobileNav } from "@/components/ui/mobile-nav"
import {
  Sidebar,
  SidebarTrigger,
  useSidebarState,
  type SidebarLabels,
  type SidebarState,
} from "@/components/ui/sidebar"
import { setSidebarDrawerOpen } from "@/components/ui/sidebar-trigger"
import { SkipLink } from "@/components/ui/skip-link"
import { Topbar } from "@/components/ui/topbar"
import { ShellSidebarContext, useShellRoutes, useShellSidebar } from "@/components/ui/use-shell"
import { cn } from "@/lib/utils"

type ShellLabels = {
  skipToContent: string
  /** Names the sidebar's navigation landmark and its drawer. */
  sidebar: string
  /** Names the bottom bar's navigation landmark; keep it apart from `sidebar`, as both can show at once. */
  mobileNav: string
  /** The palette's group of routes. */
  goTo: string
  more: string
  /** The search triggers in the topbar. */
  openSearch: string
  /** The palette dialog's title. */
  palette: string
  /** Names the palette's input; keep it apart from `palette` and `openSearch`, so agents tell them apart. */
  search: string
  searchPlaceholder?: string
  /** Shown when nothing in the palette matches. */
  empty: string
  openNavigation: string
  closeNavigation: string
  collapseSidebar: string
  expandSidebar: string
}

const shellLabels: ShellLabels = {
  skipToContent: "Skip to content",
  sidebar: "Main",
  mobileNav: "Bottom bar",
  goTo: "Go to",
  more: "More",
  openSearch: "Search",
  palette: "Command palette",
  search: "Find a page or command",
  empty: "No results",
  openNavigation: "Open navigation",
  closeNavigation: "Close navigation",
  collapseSidebar: "Collapse sidebar",
  expandSidebar: "Expand sidebar",
}

type ShellProps<Route extends ShellRoute = ShellRoute> = Omit<ComponentProps<"div">, "children"> & {
  /**
   * Every route, in order: the sidebar, the bottom bar (`mobile`), its More sheet and the palette's Go to group come
   * from it. A route's `placements` limits where it shows.
   */
  routes: readonly Route[]
  /** The sidebar's groups, in order, with their labels and tone. Without them, routes group by their `group` text. */
  groups?: readonly ShellRouteGroup[]
  /** Marks the current route (`aria-current="page"`, the primary fill): its href, or a matcher for nested routes. */
  currentHref?: ShellCurrent<Route>
  /**
   * Takes over following a route from the sidebar, the bottom bar and the palette, for a client-side router:
   * `(href) => router.push(href)`. Without it, routes are plain links (fast links follow them on press), and a
   * hash router's `#/route` hrefs just work. Keep it stable (module level, `useCallback` or React Compiler) so a
   * navigation re-renders only the two routes whose current state changed.
   */
  onNavigate?: (href: string, route: Route) => void
  /** A logo or product name, after the sidebar trigger. */
  brand?: ReactNode
  /** The topbar's end: notifications, appearance, the account menu. */
  actions?: ReactNode
  /** More `CommandGroup`s in the palette, after Go to. */
  commandGroups?: ReactNode
  /** Runs the commands of `commandGroups` by value; the palette closes once a returned Promise settles. */
  onCommand?: (value: string) => unknown
  /**
   * Above the sidebar's routes, like a brand, a workspace switcher or a caption. Hidden while the sidebar is a rail;
   * in the narrow drawer it sits under the drawer's title.
   */
  sidebarHeader?: ReactNode
  /** Below the sidebar's routes, like an account or a plan. */
  sidebarFooter?: ReactNode
  labels?: Partial<ShellLabels>
  /** Remembers whether the sidebar is collapsed in localStorage under this key. */
  storageKey?: string
  defaultCollapsed?: boolean
  /**
   * The sidebar's state, from your own `useSidebarState()`, to read or toggle it outside the Shell. Then `storageKey`
   * and `defaultCollapsed` go to that call instead. Inside the Shell, `useShellSidebar()` returns the state either way.
   */
  sidebar?: SidebarState
  /**
   * A shortcut that toggles the sidebar, like `"mod+b"`: it collapses or expands it on wide screens and opens the
   * drawer on narrow ones. Off by default. The topbar's trigger shows it and `ShortcutsDialog` lists it.
   */
  sidebarShortcut?: string
  /** `rail` keeps icons when collapsed; `hide` slides the sidebar away. Rail when every route has an icon. */
  collapse?: "rail" | "hide"
  /** Opens the palette from anywhere; `false` when the page already uses it. */
  searchShortcut?: string | false
  /** The palette's search text, to control it. Without it, every open starts empty (or from `defaultSearchQuery`). */
  searchQuery?: string
  /** The search text each open of the palette starts from, when `searchQuery` doesn't control it. */
  defaultSearchQuery?: string
  onSearchQueryChange?: ShellSearchProps["onQueryChange"]
  /** At the bottom of the palette, like key hints (`<Kbd>↑</Kbd><Kbd>↓</Kbd>` and their words). Nothing by default. */
  searchFooter?: ReactNode
  /**
   * `fill` gives `<main>` the height left under the topbar and above the bottom bar (`--shell-column-height`), so a
   * page like a DocumentWorkspace fills it with `h-full`; its content scrolls inside. `flow` (default) lets the page
   * scroll. A route's `main` overrides it while that route is current.
   */
  main?: ShellMain
  /** The id of the `<main>` landmark, the skip link's target. */
  mainId?: string
  /** `div` when the page already has its `<main>`, like a preview inside another page. */
  as?: "main" | "div"
  children?: ReactNode
}

// The theme's `narrow:` breakpoint, so the drawer, the bottom bar and the stacked layout switch together.
const narrowQuery = "(width <= 47.5rem)"

// Derived below the root, where a consumer's `--shell-height` is set.
const columns = {
  "--shell-column-height": "calc(var(--shell-height) - var(--topbar-height))",
  "--shell-scroll-margin": "calc(var(--topbar-height) + var(--gap-group))",
  "--shell-column-height-above-bar": "calc(var(--shell-column-height) - var(--mobile-nav-offset))",
} as CSSProperties

/**
 * An application's shell from its routes: a skip link, a topbar with the sidebar trigger, a brand, search and
 * actions, a grouped sidebar that sticks under it (a drawer on narrow screens), a ⌘K palette that goes to any route,
 * a bottom bar on narrow screens and the main landmark. `--shell-height` (the viewport by default) is the height
 * of the box that scrolls the page, for a shell inside a pane.
 */
function Shell<Route extends ShellRoute>({
  routes,
  groups,
  currentHref,
  onNavigate,
  brand,
  actions,
  commandGroups,
  onCommand,
  sidebarHeader,
  sidebarFooter,
  labels: overrides,
  storageKey,
  defaultCollapsed,
  sidebar: sidebarState,
  sidebarShortcut,
  collapse,
  searchShortcut = "mod+k",
  searchQuery,
  defaultSearchQuery,
  onSearchQueryChange,
  searchFooter,
  main = "flow",
  mainId = "main",
  as: Main = "main",
  className,
  style,
  children,
  ...props
}: ShellProps<Route>) {
  const labels = { ...shellLabels, ...overrides }
  const collapseMode =
    collapse ?? (routes.every((route) => route.icon !== undefined || !placedIn(route, "sidebar")) ? "rail" : "hide")
  const sidebarLabels: Partial<SidebarLabels> = {
    open: labels.openNavigation,
    close: labels.closeNavigation,
    collapse: labels.collapseSidebar,
    expand: labels.expandSidebar,
  }
  const ownSidebar = useSidebarState({ storageKey, defaultCollapsed })
  const sidebar = sidebarState ?? ownSidebar
  const [search] = useState(() => createCommandDialogController())
  const { sections, paletteSections, mobile, currentId } = useShellRoutes(routes, groups, currentHref)
  // Stable while the routes and onNavigate are, so a navigation re-renders only the items whose current changed.
  const navigate = useCallback(
    (id: string) => {
      const route = routes.find((candidate) => candidate.id === id)
      if (!route) return
      setSidebarDrawerOpen(sidebar.controller, false)
      if (onNavigate) onNavigate(route.href, route)
      else location.assign(route.href)
    },
    [routes, onNavigate, sidebar.controller],
  )
  const mobileNav = useMobileNavItems(mobile, currentId, onNavigate ? navigate : undefined)
  const hasMobileNav = mobileNav.items.length > 0
  const mainLayout = routes.find((route) => route.id === currentId)?.main ?? main

  return (
    <ShellSidebarContext value={sidebar}>
      <div
        data-slot="shell"
        className={cn("flex min-h-(--shell-height) w-full min-w-0 flex-col", className)}
        style={{ "--shell-height": "100dvh", ...style } as CSSProperties}
        {...props}
      >
        <SkipLink target={mainId}>{labels.skipToContent}</SkipLink>
        <Topbar
          leading={
            <>
              <SidebarTrigger
                {...sidebar.triggerProps}
                narrowQuery={narrowQuery}
                labels={sidebarLabels}
                shortcut={sidebarShortcut}
              />
              {brand}
            </>
          }
          center={
            <CommandDialogTrigger
              controller={search}
              shortcut={searchShortcut === false ? undefined : searchShortcut}
              className="w-full max-w-sm"
            >
              <span className="inline-flex min-w-0 items-center gap-inline">
                <SearchIcon className="size-4 shrink-0" />
                <span className="truncate">{labels.openSearch}</span>
              </span>
              <CommandDialogShortcut />
            </CommandDialogTrigger>
          }
          centerCompact={
            <CommandDialogOpenButton controller={search} variant="ghost" size="icon" aria-label={labels.openSearch}>
              <SearchIcon />
            </CommandDialogOpenButton>
          }
          trailing={actions}
        />
        <ShellSearch
          controller={search}
          sections={paletteSections}
          currentId={currentId}
          navigate={navigate}
          labels={labels}
          commandGroups={commandGroups}
          onCommand={onCommand}
          query={searchQuery}
          defaultQuery={defaultSearchQuery}
          onQueryChange={onSearchQueryChange}
          footer={searchFooter}
        />
        <div data-slot="shell-body" className="flex min-w-0 flex-1 items-start" style={columns}>
          <div
            data-slot="shell-sidebar"
            className="sticky top-(--topbar-height) flex h-(--shell-column-height) shrink-0 narrow:contents"
          >
            <Sidebar
              label={labels.sidebar}
              {...sidebar.sidebarProps}
              collapse={collapseMode}
              trigger={false}
              narrowQuery={narrowQuery}
              labels={sidebarLabels}
              header={sidebarHeader}
              footer={sidebarFooter}
            >
              <ShellSidebarSections sections={sections} currentId={currentId} navigate={navigate} />
            </Sidebar>
          </div>
          <Main
            id={mainId}
            tabIndex={-1}
            data-slot="shell-main"
            data-main={mainLayout}
            // Anchors, focus and scrollIntoView stop below the topbar and above the bottom bar.
            className={cn(
              "flex min-w-0 flex-1 flex-col self-stretch focus:outline-none **:scroll-mt-(--shell-scroll-margin)",
              hasMobileNav && "narrow:**:scroll-mb-(--mobile-nav-offset)",
              mainLayout === "fill" && "h-(--shell-column-height) min-h-0 overflow-auto",
              mainLayout === "fill" && hasMobileNav && "narrow:h-(--shell-column-height-above-bar)",
            )}
          >
            {children}
          </Main>
        </div>
        {hasMobileNav && (
          // Sticky in the flow rather than fixed: it keeps its own height at the end of the shell, so the page always
          // ends above it, and it stays inside a pane or an iframe.
          <MobileNav
            label={labels.mobileNav}
            items={mobileNav.items}
            overflow={mobileNav.overflow}
            moreLabel={labels.more}
            className="sticky"
          />
        )}
      </div>
    </ShellSidebarContext>
  )
}

export { Shell, shellLabels, useShellSidebar }
export type { ShellMain, ShellRoute, ShellPlacement, ShellRouteGroup, ShellCurrent, ShellLabels, ShellProps }
